"""Agent discovery, the compose file list, and the writer of the generated files.

Nothing runs this yet: step 3a switches the compose commands to it. See
plans/platformctl/design.md, "Agent discovery" and "The compose entry file".
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from platformctl.config import REGISTRY, PlatformConfig
from platformctl.system import envfile

BUILD_CACHE_FILE = "docker-compose.build-cache.yml"
"""The compose file that imports the registry build cache."""
LABELS_FILE = "docker-compose.labels.yml"
"""The generated compose file that puts the platform labels on every service (from step 3b)."""


@dataclass(frozen=True)
class Agent:
    """One agent found on disk, with why it is included."""

    directory: Path
    """The agent's folder."""
    compose_file: Path
    """The agent's `docker-compose.yml`."""
    card: Path | None
    """The agent's `agent_card.json`, or None when it has none."""
    group: str  # in-tree | debug | optional
    """Why the agent is included: `in-tree`, `debug` or `optional`."""

    @property
    def name(self) -> str:
        """The agent's name, which is its folder's name."""
        return self.directory.name


def _agents_in(base: Path, depth_dir: str, group: str) -> list[Agent]:
    """Find the agents with a compose file one level below `base/depth_dir`."""
    folder = base / depth_dir
    if not folder.is_dir():
        return []
    found = []
    for compose in sorted(folder.glob("*/docker-compose.yml")):
        card = compose.parent / "agent_card.json"
        found.append(Agent(compose.parent, compose, card if card.exists() else None, group))
    return found


def discover_agents(root: Path, config: PlatformConfig) -> list[Agent]:
    """`agents/*`, plus `agents/debug-agents/*` with DEBUG_AGENTS and `agents/optional/*` with OPTIONAL_AGENTS."""
    agents = _agents_in(root, "agents", "in-tree")
    if config.flag("DEBUG_AGENTS"):
        agents += _agents_in(root, "agents/debug-agents", "debug")
    if config.flag("OPTIONAL_AGENTS"):
        agents += _agents_in(root, "agents/optional", "optional")
    return agents


def generated_agent_dirs(root: Path) -> list[Path]:
    """The agent folders the generated `docker-compose.agents.yml` includes, plus `agents/client-agent`.

    This is what `make check` read with `sed` from the same file: the agents a start actually
    brought up, so the `ng-*` targets check what they started. The client agent is always checked.
    """
    folders = [root / "agents" / "client-agent"]
    generated = root / "docker-compose.agents.yml"
    if generated.exists():
        for line in generated.read_text(encoding="utf-8").splitlines():
            entry = line.strip()
            if entry.startswith("- ") and entry.endswith("/docker-compose.yml"):
                folder = root / entry[2 : -len("/docker-compose.yml")].strip()
                if folder not in folders:
                    folders.append(folder)
    return folders


def compose_file_list(
    root: Path, config: PlatformConfig, agents: list[Agent], *, generated_agents: bool = True
) -> list[str]:
    """The files the entry file includes, in order.

    Base, system-test, agents, DeepLynx, override. The build-cache file is an image decision
    that `generate()` adds. With `generated_agents=False` (`--no-generate`) the agents file is
    included only if it already exists.
    """
    files = ["docker-compose.yml"]
    if config.flag("PROMETHEUS_SYSTEM_TESTING"):
        files.append("docker-compose.system-test.yml")
    if agents if generated_agents else (root / "docker-compose.agents.yml").exists():
        files.append("docker-compose.agents.yml")
    if config.flag("LOCAL_DEEPLYNX"):
        files.append("docker-compose.deeplynx.yml")
    if (root / "docker-compose.override.yml").exists():
        files.append("docker-compose.override.yml")
    return files


def render_agents_file(root: Path, agents: list[Agent]) -> str:
    """Return the text of `docker-compose.agents.yml`, which includes each agent's compose file."""
    lines = [
        "# Generated by platformctl; do not edit. Rerun ./platformctl agents generate",
        "# after checking out or removing agent submodules.",
        "",
        "include:",
    ]
    lines += [f"  - {a.compose_file.relative_to(root).as_posix()}" for a in agents]
    return "\n".join(lines) + "\n"


def render_entry_file(project: str, paths: list[str]) -> str:
    """Return the text of `docker-compose.platform.yml`, the entry file that includes the compose files."""
    listed = ", ".join(paths)
    return (
        "# docker-compose.platform.yml\n"
        "# Generated by platformctl; do not edit. Rerun ./platformctl agents generate\n"
        "# after changing LOCAL_SDK, the base-image pin or the agents.\n"
        f"name: {project}\n"
        "include:\n"
        f"  - path: [{listed}]\n"
        "    env_file: [.platform.env]\n"
    )


def render_platform_env(values: dict[str, str]) -> str:
    """Derived, non-secret values only. Refuses any key the registry doesn't mark safe."""
    for key in values:
        setting = REGISTRY.get(key)
        if not (setting and setting.safe):
            raise ValueError(f"{key} is not marked safe to print and can't go in .platform.env")
    body = "".join(f"{k}={envfile._format(v)}\n" for k, v in values.items())
    return "# Generated by platformctl; settings go in .env, not here.\n" + body


def derived_values(config: PlatformConfig, *, build_cache: bool, arch: str) -> dict[str, str]:
    """Return the values the tool derives for `.platform.env`: the base image and the build cache."""
    repo, tag = config.base_image()
    values = {
        "PROMETHEUS_API_BASE_IMAGE_REPO": repo,
        "PROMETHEUS_API_BASE_IMAGE_HASH": tag,
        "USE_BUILD_CACHE": "true" if build_cache else "false",
    }
    if build_cache:
        values["BUILD_CACHE"] = config.get("BUILD_CACHE")
        values["BUILD_CACHE_PLATFORM"] = config.get("BUILD_CACHE_PLATFORM") or arch
    return values


def write_generated(
    root: Path,
    config: PlatformConfig,
    agents: list[Agent],
    *,
    build_cache: bool,
    arch: str,
    generated_agents: bool = True,
) -> dict[str, Path]:
    """Write the agents file, the entry file and `.platform.env`. Returns what was written."""
    files = compose_file_list(root, config, agents, generated_agents=generated_agents)
    if build_cache:
        files.append(BUILD_CACHE_FILE)
    written = {
        "entry": root / "docker-compose.platform.yml",
        "env": root / ".platform.env",
    }
    if generated_agents and agents:
        written["agents"] = root / "docker-compose.agents.yml"
        envfile.write_atomic(written["agents"], render_agents_file(root, agents))
    envfile.write_atomic(written["entry"], render_entry_file(config.project, files))
    envfile.write_atomic(
        written["env"], render_platform_env(derived_values(config, build_cache=build_cache, arch=arch))
    )
    return written
